/// Configure all HTTP routes for this module using Axum and BackboneCrudHandler.
///
/// Each entity gets 12 standard Backbone CRUD endpoints:
/// 1. GET /api/v1/{collection} - List with pagination
/// 2. POST /api/v1/{collection} - Create
/// 3. GET /api/v1/{collection}/:id - Get by ID
/// 4. PUT /api/v1/{collection}/:id - Full update
/// 5. PATCH /api/v1/{collection}/:id - Partial update
/// 6. DELETE /api/v1/{collection}/:id - Soft delete
/// 7. POST /api/v1/{collection}/bulk - Bulk create
/// 8. POST /api/v1/{collection}/upsert - Upsert
/// 9. GET /api/v1/{collection}/trash - List deleted
/// 10. POST /api/v1/{collection}/:id/restore - Restore
/// 11. DELETE /api/v1/{collection}/empty - Empty trash
/// 12. GET /api/v1/{collection}/:id/deleted - Get deleted by ID
pub fn configure_routes(services: HttpServices) -> Router {
    Router::new()
        // Question routes (12 Backbone endpoints)
        .merge(create_question_routes(services.question))
        // QuestionAnswer routes (12 Backbone endpoints)
        .merge(create_question_answer_routes(services.question_answer))
        // SurveyQuestionTriggeringAnswer routes (12 Backbone endpoints)
        .merge(create_survey_question_triggering_answer_routes(services.survey_question_triggering_answer))
        // Survey routes (12 Backbone endpoints)
        .merge(create_survey_routes(services.survey))
        // SurveySurveyRestrictUser routes (12 Backbone endpoints)
        .merge(create_survey_survey_restrict_user_routes(services.survey_survey_restrict_user))
        // SurveySurveyLang routes (12 Backbone endpoints)
        .merge(create_survey_survey_lang_routes(services.survey_survey_lang))
        // UserInput routes (READ-ONLY — append-only/event-sourced entity; writes arrive via the event handlers)
        .merge(create_user_input_read_routes(services.user_input))
        // UserInputLine routes (READ-ONLY — append-only/event-sourced entity; writes arrive via the event handlers)
        .merge(create_user_input_line_read_routes(services.user_input_line))
        // SurveyUserInputPredefinedQuestion routes (12 Backbone endpoints)
        .merge(create_survey_user_input_predefined_question_routes(services.survey_user_input_predefined_question))
}

